94	// New creates a new OpenAI-compatible provider.
95	func New(cfg Config) *Provider {
96		serverAddress, serverPort := endpointMetadata(cfg.BaseURL)
97		providerSystem := "openai"
98		if cfg.ProviderSystem != "" {
99			providerSystem = cfg.ProviderSystem
100		}
101		providerName := cfg.ProviderName
102		if providerName == "" {
103			providerName = providerSystem
104		}
105		parser := cfg.QuotaHeaderParser
106		if parser == nil && cfg.QuotaSignalObserver != nil {
107			// Default to OpenAI-shaped header parsing when no explicit parser is
108			// supplied. OpenRouter overrides this via Config.QuotaHeaderParser.
109			parser = quotaheaders.ParseOpenAI
110		}
111		runtimeObserver := func(headers http.Header, latency time.Duration, callErr error) {
112			runtimesignals.RecordResponse(providerName, headers, latency, providerSystem)
113			if err := runtimesignals.Observe(context.Background(), providerName, providerSystem, cfg.BaseURL, headers, latency, callErr); err != nil && cfg.Logger != nil {
114				cfg.Logger.Debug("runtime signal observe failed", "provider", providerName, "err", err)
115			}
116		}
117		p := &Provider{
118			client: openaicompat.NewClient(openaicompat.Config{
119				BaseURL:               cfg.BaseURL,
120				APIKey:                cfg.APIKey,
121				Headers:               cfg.Headers,
122				QuotaHeaderParser:     parser,
123				QuotaSignalObserver:   cfg.QuotaSignalObserver,
124				RuntimeSignalObserver: runtimeObserver,
125			}),
126			model:              cfg.Model,
127			modelPattern:       cfg.ModelPattern,
128			knownModels:        cfg.KnownModels,
129			baseURL:            cfg.BaseURL,
130			apiKey:             cfg.APIKey,
131			providerName:       providerName,
132			providerSystem:     providerSystem,
133			capabilities:       cfg.Capabilities,
134			usageCost:          cfg.UsageCostAttribution,
135			serverAddress:      serverAddress,
136			serverPort:         serverPort,
137			reasoningDefault:   cfg.Reasoning,
138			modelReasoningWire: cfg.ModelReasoningWire,
139			logger:             cfg.Logger,
140		}
141		if p.logger == nil {
142			p.logger = slog.Default()
143		}
144		return p
145	}
