147	// DiscoveredModels returns the full ranked list of models discovered from the
148	// server's /v1/models endpoint. Returns nil if the provider has a statically
149	// configured model or if discovery has not yet run (i.e. no request has been
150	// made yet). Call EnsureDiscovered to force discovery without making a chat
151	// request.
152	func (p *Provider) DiscoveredModels() []ScoredModel {
153		return p.discoveredModels
154	}
