197	func (p *Provider) Chat(ctx context.Context, messages []agent.Message, tools []agent.ToolDef, opts agent.Options) (agent.Response, error) {
198		model, err := p.resolveModel(ctx)
199		if err != nil {
200			return agent.Response{}, err
201		}
202		if opts.Model != "" {
203			model = opts.Model
204		}
205	
206		reqOpts, reasoningEmitted, err := p.compatRequestOptions(model, opts)
207		if err != nil {
208			return agent.Response{}, err
209		}
210	
211		result, err := p.client.Chat(ctx, model, messages, tools, reqOpts)
212		if err != nil {
213			return agent.Response{}, fmt.Errorf("openai: %w", err)
214		}
215	
216		resp := agent.Response{
217			Model:        result.Model,
218			Content:      result.Content,
219			FinishReason: result.FinishReason,
220			ToolCalls:    result.ToolCalls,
221			Usage:        result.Usage,
222		}
223		resp.Attempt = p.attemptMetadata(model, result.Model, &agent.CostAttribution{
224			Source: agent.CostSourceUnknown,
225		}, reasoningEmitted)
226		if cost := p.costAttribution(result.RawUsage); cost != nil {
227			resp.Attempt.Cost = cost
228		}
229		return resp, nil
230	}
