244	// ChatStream implements agent.StreamingProvider for token-level streaming.
245	func (p *Provider) ChatStream(ctx context.Context, messages []agent.Message, tools []agent.ToolDef, opts agent.Options) (<-chan agent.StreamDelta, error) {
246		model, err := p.resolveModel(ctx)
247		if err != nil {
248			return nil, err
249		}
250		if opts.Model != "" {
251			model = opts.Model
252		}
253	
254		reqOpts, reasoningEmitted, err := p.compatRequestOptions(model, opts)
255		if err != nil {
256			return nil, err
257		}
258	
259		return p.client.ChatStream(ctx, model, messages, tools, reqOpts, openaicompat.StreamHooks{
260			Cost: p.costAttribution,
261			Attempt: func(responseModel string, cost *agent.CostAttribution) *agent.AttemptMetadata {
262				return p.attemptMetadata(model, responseModel, streamAttemptCost(cost), reasoningEmitted)
263			},
264		})
265	}
