354	func applyReasoningAliasMap(policy reasoningpolicy.Policy, aliasMap map[string]string) (reasoningpolicy.Policy, bool) {
355		if policy.Kind != reasoningpolicy.KindNamed || len(aliasMap) == 0 {
356			return policy, false
357		}
358		mapped, ok := aliasMap[string(policy.Value)]
359		if !ok || mapped == "" || mapped == string(policy.Value) {
360			return policy, false
361		}
362		return reasoningpolicy.Policy{
363			Kind:  reasoningpolicy.KindNamed,
364			Value: reasoningpolicy.Reasoning(mapped),
365		}, true
366	}
