368	// reasoningRequestOptions builds per-request options. For thinking models
369	// (Qwen3, DeepSeek-R1 etc.) apply provider-specific non-standard body fields
370	// only when the concrete provider declares the matching wire support.
371	func (p *Provider) reasoningRequestOptions(model string, opts agent.Options) ([]option.RequestOption, reasoningpolicy.Reasoning, error) {
372		policy, err := reasoningpolicy.Parse(opts.Reasoning)
373		if err != nil {
374			return nil, "", err
375		}
376		explicitRequest := policy.IsSet()
377		if !explicitRequest {
378			policy, err = reasoningpolicy.Parse(p.reasoningDefault)
379			if err != nil {
380				return nil, "", err
381			}
382		}
383	
384		if !policy.IsSet() || policy.Kind == reasoningpolicy.KindAuto {
385			return nil, "", nil
386		}
387	
388		// Catalog reasoning_wire metadata gates the wire shape before any
389		// provider-specific encoding runs. Models flagged as reasoning_wire=none
390		// have no reasoning surface at all; an explicit non-off request is a
391		// catalog/wire mismatch and must surface as an error rather than be
392		// silently dropped. Models flagged as reasoning_wire=model_id encode the
393		// reasoning level in the model name (e.g. fixed-variant Qwen3.6) and the
394		// upstream endpoint cannot honor an external reasoning toggle, so the
395		// reasoning field must be stripped from the wire body.
396		catalogWire := p.modelReasoningWireFor(model)
397		switch catalogWire {
398		case "none":
399			if explicitRequest && !policy.IsExplicitOff() {
400				return nil, "", fmt.Errorf("openai: model %q has reasoning_wire=none; explicit reasoning=%q is not supported", model, policy.Value)
401			}
402			return nil, "", nil
403		case "model_id":
404			return nil, "", nil
405		}
406	
407		if !p.SupportsThinking() {
408			if policy.IsExplicitOff() {
409				return nil, reasoningpolicy.ReasoningOff, nil
410			}
411			if explicitRequest {
412				return nil, "", fmt.Errorf("openai: reasoning=%q is not supported by provider type %q", policy.Value, p.providerSystem)
413			}
414			return nil, "", nil
415		}
416	
417		if policy.IsExplicitOff() {
418			switch p.thinkingWireFormat() {
419			case ThinkingWireFormatQwen:
420				// For Qwen wire format, emit enable_thinking: false for any model unless strict matching is enabled
421				// and the model is not Qwen-named. Providers like llamaserver should emit the envelope regardless.
422				if !isQwenModel(model) && p.strictThinkingModelMatch() {
423					if explicitRequest {
424						return nil, "", fmt.Errorf("openai: qwen reasoning control is not supported for model %q on provider type %q", model, p.providerSystem)
425					}
426					return nil, "", nil
427				}
428				return []option.RequestOption{
429					option.WithJSONSet("chat_template_kwargs", map[string]interface{}{
430						"enable_thinking": false,
431					}),
432				}, reasoningpolicy.ReasoningOff, nil
433			case ThinkingWireFormatOpenRouter:
434				return []option.RequestOption{option.WithJSONSet("reasoning", map[string]interface{}{
435					"effort": "none",
436				})}, reasoningpolicy.ReasoningOff, nil
437			case ThinkingWireFormatOpenAIEffort:
438				return []option.RequestOption{option.WithJSONSet("think", false)}, reasoningpolicy.ReasoningOff, nil
439			}
440			return nil, reasoningpolicy.ReasoningOff, nil
441		}
442	
443		if p.thinkingWireFormat() == ThinkingWireFormatOpenRouter {
444			return openRouterReasoningOptions(policy, model, catalogWire)
445		}
446		if p.thinkingWireFormat() == ThinkingWireFormatOpenAIEffort {
447			return openAIEffortReasoningOptions(policy, p.protocolCapabilities().ReasoningAliasMap, p.logger, model, p.providerSystem)
448		}
449		// For Qwen wire format, only enforce strict model matching if explicitly requested by the provider.
450		// Providers like llamaserver (which run arbitrary GGUF models) should emit Qwen controls for any model
451		// and let the server ignore them if unsupported. L1 introspection can refine this at construction time.
452		if p.thinkingWireFormat() == ThinkingWireFormatQwen && !isQwenModel(model) && p.strictThinkingModelMatch() {
453			if explicitRequest {
454				return nil, "", fmt.Errorf("openai: qwen reasoning control is not supported for model %q on provider type %q", model, p.providerSystem)
455			}
456			return nil, "", nil
457		}
458	
459		// Qwen and ThinkingMap providers can only express a token budget on the
460		// wire. If the catalog declares effort wire for this model, degrade
461		// gracefully: snap KindTokens to the nearest PortableBudgets tier so the
462		// downstream budget calculation uses a standard value. The model still
463		// works; the catalog entry is simply mis-classified.
464		if catalogWire == "effort" {
465			p.logger.Warn("catalog declares effort wire but provider only supports budget wire",
466				"model", model,
467				"provider", p.providerSystem,
468			)
469			if policy.Kind == reasoningpolicy.KindTokens {
470				tier := reasoningpolicy.NearestTierForTokens(policy.Tokens)
471				policy = reasoningpolicy.Policy{Kind: reasoningpolicy.KindNamed, Value: tier}
472			}
473		}
474	
475		thinkingBudget, err := reasoningpolicy.BudgetFor(policy, nil, 0)
476		if err != nil {
477			return nil, "", fmt.Errorf("openai: %w", err)
478		}
479		if thinkingBudget <= 0 {
480			return nil, "", nil
481		}
482		emitted := reasoningpolicy.ReasoningTokens(thinkingBudget)
483	
484		switch p.thinkingWireFormat() {
485		case ThinkingWireFormatQwen:
486			return []option.RequestOption{
487				option.WithJSONSet("chat_template_kwargs", map[string]interface{}{
488					"enable_thinking": true,
489					"thinking_budget": thinkingBudget,
490				}),
491			}, emitted, nil
492		case "", ThinkingWireFormatThinkingMap:
493			return []option.RequestOption{option.WithJSONSet("thinking", map[string]interface{}{
494				"type":          "enabled",
495				"budget_tokens": thinkingBudget,
496			})}, emitted, nil
497		default:
498			return nil, "", fmt.Errorf("openai: unsupported thinking wire format %q for provider type %q", p.thinkingWireFormat(), p.providerSystem)
499		}
500	}
501	
502	// openAIEffortReasoningOptions builds the flat top-level reasoning_effort wire
503	// used by ds4 / deepseek-v4-flash. Named tiers are emitted as-is; token
504	// budgets are snapped to the nearest PortableBudgets tier via NearestTierForTokens.
505	// Alias maps from live introspection are applied after snapping so ds4's
506	// low/medium/xhigh→high aliasing is reflected on the wire.
507	func openAIEffortReasoningOptions(policy reasoningpolicy.Policy, aliasMap map[string]string, logger *slog.Logger, model, providerSystem string) ([]option.RequestOption, reasoningpolicy.Reasoning, error) {
508		var tier reasoningpolicy.Reasoning
509		switch policy.Kind {
510		case reasoningpolicy.KindTokens:
511			tier = reasoningpolicy.NearestTierForTokens(policy.Tokens)
512		case reasoningpolicy.KindNamed:
513			tier = policy.Value
514		default:
515			return nil, "", fmt.Errorf("openai: unsupported OpenAI effort reasoning policy kind %q", policy.Kind)
516		}
517		normalized, changed := applyReasoningAliasMap(reasoningpolicy.Policy{Kind: reasoningpolicy.KindNamed, Value: tier}, aliasMap)
518		if changed && logger != nil {
519			logger.Warn("reasoning alias map overrode requested tier",
520				"model", model,
521				"provider", providerSystem,
522				"reasoning_intent", string(tier),
523				"reasoning_emitted", string(normalized.Value),
524				"reasoning_emitted_reason", providerSystem+" alias map",
525			)
526			tier = normalized.Value
527		}
528		return []option.RequestOption{option.WithJSONSet("reasoning_effort", string(tier))}, tier, nil
529	}
