531	// modelReasoningWireFor returns the catalog reasoning_wire value for the
532	// given model, defaulting to "provider" when the model is not catalog-known.
533	// Returned values are normalized: only "model_id" and "none" trigger
534	// catalog-driven wire overrides; everything else falls through to the
535	// provider's protocol capability path.
536	func (p *Provider) modelReasoningWireFor(model string) string {
537		if p.modelReasoningWire == nil || model == "" {
538			return ""
539		}
540		return p.modelReasoningWire[model]
541	}
