543	func isQwenModel(model string) bool {
544		return strings.Contains(strings.ToLower(model), "qwen")
545	}
546	
547	// openRouterReasoningOptions builds the OpenRouter nested reasoning object.
548	// model is included for structured-warning logs.
549	// wire is the catalog reasoning_wire value for the model:
550	//   - "" or "provider": pick wire shape from policy.Kind (backwards-compat)
551	//   - "effort": always emit reasoning.effort string; snap KindTokens to nearest tier
552	//   - "tokens": always emit reasoning.max_tokens int; expand KindNamed via PortableBudgets
553	func openRouterReasoningOptions(policy reasoningpolicy.Policy, model, wire string) ([]option.RequestOption, reasoningpolicy.Reasoning, error) {
554		reasoning := map[string]interface{}{}
555		var emitted reasoningpolicy.Reasoning
556		switch wire {
557		case "effort":
558			var tier reasoningpolicy.Reasoning
559			switch policy.Kind {
560			case reasoningpolicy.KindTokens:
561				tier = reasoningpolicy.NearestTierForTokens(policy.Tokens)
562			case reasoningpolicy.KindNamed:
563				tier = policy.Value
